const { regClass } = Laya;
import { LayerManager } from "../../common/LayerManager";
import { GameEvent } from "../../global/event/GameEvent";
import Signal from "../../global/event/Signal";
import { HeadItem } from "../../data/sheetItem/HeadItem";
import HttpCmd from "../../network/HttpCmd";
import { Dictionary } from "../../utils/Dictionary";
import { ChangeHeadDialogBase } from "./ChangeHeadDialog.generated";
import GameLanguageMgr from "../../common/GameLanguageMgr";
import GlobalDataManager from "../../global/GlobalDataManager";
import SheetDataManager from "../../global/SheetDataManager";
import { com } from "../../network/pb/socket";
import HallWebSocket from "../../network/HallWebSocket";
import { SocketDataUtil } from "../../utils/SocketDataUtil";

@regClass('BmtPy79ySCyg4IuEQC4zsQ==')
export class ChangeHeadDialog extends ChangeHeadDialogBase {
    public m_strName: string = "我是OpenSceneRuntime";
    public m_iLayerType: number = LayerManager.M_POP;
    public m_iPositionType: number = LayerManager.CENTER;
    private dialogType: number = 0; // 0: 注册页面修改头像, 1: 个人中心修改头像

    public constructor() {
        super();
    }

    public setOpenData(data: any) {
        if (data && data.length > 0) {
            this.dialogType = data[0];
        }
    }

    onEnable(): void {
        this.list_head.vScrollBarSkin = "";
        this.btn_confirm.on(Laya.Event.CLICK, this, this.onRegister);
        this.btn_custom.on(Laya.Event.CLICK, this, this.onBtnChangePic);
        this.btn_close.on(Laya.Event.CLICK, this, this.close);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_CHANGE_INFO, this, this.onChangeInfoResponse);
        this.initContainer();
    }

    private initContainer(): void {
        this.list_head.vScrollBarSkin = "";
        this.list_head.selectHandler = new Laya.Handler(this, this.handleSelectHead);
        this.createHeadList();
    }

    private handleSelectHead(index: number): void {
        if (index != -1) {
            let headItem: HeadItem = this.list_head.selectedItem;
            GlobalDataManager.headId = headItem.id;
            // this.playerIcon.headSkin = GlobalDataManager.headId;
        }
    }

    private createHeadList(): void {
        let m_dicHead: Dictionary = SheetDataManager.m_dicHead;
        this.list_head.array = m_dicHead.values;
        this.list_head.visible = true;
        let selectIndex = -1;
        let i = 0;
        // this.playerIcon.headSkin = GlobalDataManager.headId; //设置当前角色头像；

        for (let entry of m_dicHead.values) {
            if (entry.id == GlobalDataManager.headId) {
                selectIndex = i;
                break;
            }
            i++;
        }
        this.list_head.selectedIndex = selectIndex;
    }

    /** 切换 用户上传图片  */
    onBtnChangePic(): void {
        var zIndex = Laya.Render.canvas.style.zIndex;
        var uploadP = GameLanguageMgr.getUILang("Upload picture");
        var selectI = GameLanguageMgr.getUILang("Select Image");
        var saveC = GameLanguageMgr.getUILang("Save changes");
        openUploadPic(this, zIndex, uploadP, selectI, saveC);
    }

    /** 切换 用户上传图片返回  */
    async openPicEnd(openWin: ChangeHeadDialog, base64: string): Promise<void> {
        if (base64.length > 500) {
            // this.img_head.skin = base64;
            let temp = await HttpCmd.requestPost("wxgame/player/uploadImg", { base64Str: base64 }, false, false);
            if (temp) {
                GlobalDataManager.headId = temp.imgUrl;
                // openWin.playerIcon.headSkin = temp.imgUrl;
                console.log(temp.imgUrl);
            }
        }
    }

    onRegister() {
        let headId: number = GlobalDataManager.headId;

        if (this.dialogType === 1) {
            // 个人中心修改头像，使用MSG_CHANGE_INFO协议
            this.sendChangeInfoRequest(headId);
        } else {
            // 注册页面修改头像
            Signal.event(GameEvent.EVENT_MODIFY_HEAD, [headId]);
        }

        this.close();
    }

    /**
     * 发送修改头像请求
     * @param headId 头像ID
     */
    private sendChangeInfoRequest(headId: string | number): void {
        // 使用WSM.send方式发送MSG_CHANGE_INFO协议
        const cmdId = com.snake.socket.MessageType.MSG_CHANGE_INFO;
        const requestData = com.snake.socket.CS_CHANGE_INFO.fromObject({
            type: 1, // 1表示修改头像
            value: headId.toString()
        });

        // 发送消息到服务器
        HallWebSocket.send(cmdId, requestData);

        // 更新全局数据
        GlobalDataManager.headId = headId;
    }

    /**
     * 修改头像响应回调
     */
    private onChangeInfoResponse(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.CS_CHANGE_INFO = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.CS_CHANGE_INFO);
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            console.log("SC_CHANGE_INFO", msgBody);
            GlobalDataManager.playerDto.icon = msgBody.value;
            // 通知界面刷新
            Signal.event(GameEvent.ROLE_INFO_CHANGE);
            this.close();
        }
    }

    onDisable(): void {
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_CHANGE_INFO, this, this.onChangeInfoResponse);
        this.btn_confirm.off(Laya.Event.CLICK, this, this.onRegister);
        this.btn_custom.off(Laya.Event.CLICK, this, this.onBtnChangePic);
    }
}
