    async onOpened(param: any): Promise<void> {
        // 开始动画
        // this.startBackgroundAnimation();
        this.mouseThrough = this.mouseThrough = true;
        this.headBox.mouseThrough = true;
        let mcMain: Laya.Box = this.getChildByName("mcMain") as Laya.Box;
        if (mcMain) {
            mcMain.mouseThrough = true;
        }
        this.updateTopInfo();

        // 检查URL参数中是否有room邀请信息
        const hasRoomParam = this.checkRoomInviteParams();

        if (GlobalDataManager.needToOpenJoinRoom) {
            GlobalDataManager.needToOpenJoinRoom = false;
            ModuleManager.intance.openModule(ModuleName.JoinRoomDialog, [0, 0]);
        } else if (GlobalDataManager.needToOpenPVE) {
            GlobalDataManager.needToOpenPVE = false;
            ModuleManager.intance.openModule(ModuleName.AiArenaStartDialog); //增加过渡页
        }else if(GlobalDataManager.needToOpenCustomCallBack){
            GlobalDataManager.needToOpenCustomCallBack && GlobalDataManager.needToOpenCustomCallBack.run();
        }
        // 只有在没有room参数时才更新未读邮件数量显示
        if (!hasRoomParam || !GlobalDataManager.needToOpenJoinRoom) {
            this.requestMailData();
        }

        // 更新模式盒子布局
        // this.updateModeBoxLayout();

        //EVENT ::打开主界面
        PlatFormManager.sendCustumEvent(34);
        let playerDto: PlayerDto = GlobalDataManager.playerDto;
        if (!playerDto) return;
        var nickName = null; //playerDto.name;
        showChatBtn(true, EthereumManager.walletAddress, nickName);

        // 只在本次游戏启动的第一次进入主场景时测试节点延迟
        if (!MainScene.hasTestedNodesThisSession) {
            console.log("本次游戏启动，测试节点延迟并选择最佳节点");
            MainScene.hasTestedNodesThisSession = true;
            // 执行测试所有节点并选择最佳节点的操作
            // NodeManager.testNodeDelays();
            NodeManager.getBestNode();
        } else {
            // // 即使不是首次进入，也要确保当前节点是可用的
            // this.checkCurrentNode();
        }

        // 初始化节点列表显示
        this.initNodeList();
        // this.startPing(true);
        NodeManager.startPingTime();

        // 更新模式盒子布局
        this.updateModeBoxLayout();

        if (GlobalDataManager.playerDto.club == "") {
            this.btn_guild.visible = false
        } else {
            this.btn_guild.visible = true
        }
        console.log("GlobalDataManager.playerDto.club：" + GlobalDataManager.playerDto.club);

        // 设置MarqueeManager的主界面状态为true，表示当前在主界面
        MarqueeManager.setInMainScene(true);

        // this.BannerView.visible = !GlobalDataManager.hideBanner

        // 获取并更新公告数据
        // this.getMarqueeNotices();
    }

    private currIconAni: number = 1;
    /**
     * 控制主界面按钮动画的播放
     * 该方法通过定时器循环播放spine动画，实现按钮的动态效果
     *
     * 实现逻辑：
     * 1. 使用currIconAni记录当前播放的动画序号(1-5)
     * 2. 当序号超过5时重置为1，实现循环播放
     * 3. 通过spine_+序号的方式获取对应的spine动画组件
     * 4. 设置动画可见并播放一次
     * 5. 每2000毫秒(2秒)触发一次动画播放
     */
    startBtnAni() {
        if (this.currIconAni > 5) {
            this.currIconAni = 1;
        }
        (this as any)["spine_" + this.currIconAni].play(0, false);
        (this as any)["spine_" + this.currIconAni].visible = true;
        this.currIconAni++;
        Laya.timer.once(2000, this, this.startBtnAni);
    }

