    /**
     * 销毁所有spine动画
     */
    private destroySpineAnimations(): void {
        // 遍历并销毁所有spine动画
        for (let i = 1; i < 8; i++) {
            const spineAni = (this as any)["spine_" + i];
            if (spineAni) {
                // 停止动画
                spineAni.stop();
                // 从父节点移除
                spineAni.removeSelf();
            }
        }
    }

