    private getSpineNode(anisk: AniSk): Laya.SpineSkeleton {
        if (!anisk) {
            console.warn("AniSk component is null");
            return null;
        }
        if (!anisk.box_sk) {
            console.warn("Spine skeleton node is null in AniSk component");
            return null;
        }
        return anisk.box_sk;
    }

