    private showJoinBox() {
        // SceneManager.setCurrentScene(SceneType.M_SCENE_TETRIS);
        // SceneManager.setCurrentScene(SceneType.M_SCENE_VS);
        // return;
        // 中断任何正在进行的ping测试，优先响应用户操作
        NodeManager.abortAllPingTests();

        // 记录 modeBox_2、modeBox_3、modeBox_4 的x轴目标位置
        this.joinBox.scaleX = 0;
        this.joinBox.scaleY = 0;
        this.btn_closeJoin.visible = false;
        // this.img_guangTop.visible = true;

        // 显示蒙版
        this.backLayer.visible = true;

        // 临时移除backLayer的点击事件，防止动画过程中被点击关闭
        this.backLayer.off(Laya.Event.CLICK, this, this.hideNodeBox);

        // 显示joinBox
        this.joinBox.visible = true;

        // 确保模式盒子布局正确
        this.updateModeBoxLayout();

        // 设置初始位置：所有modeBox都在modeBox_1的左侧
        // 创建动画：modeBox_2、modeBox_3、modeBox_4 从左到右移动到各自的位置上
        // 使用延迟依次播放动画，形成连续的效果
        // 增强回弹效果：调整动画时长和缓动参数

        // modeBox_2动画 - 增强回弹效果
        Laya.Tween.to(
            this.joinBox,
            { scaleX: 1.15, scaleY: 1.15 }, // 先移动超过目标位置
            200,
            Laya.Ease.linearIn, // 使用指数缓动增强回弹感
            Laya.Handler.create(this, () => {
                // 回弹到最终位置
                Laya.Tween.to(
                    this.joinBox,
                    { scaleX: 1.0, scaleY: 1.0 },
                    60,
                    Laya.Ease.linearIn, // 使用弹性缓动
                    Laya.Handler.create(this, () => {
                        // 显示关闭按钮
                        this.btn_closeJoin.visible = true;

                        // 动画完成后，重新绑定backLayer的点击事件
                        this.backLayer.on(Laya.Event.CLICK, this, this.hideNodeBox);
                    }) // 动画完成后隐藏La
                );
            })
        );
    }

