    /**
     * 邮件列表数据获取回调方法
     * @param msgBase - 服务器返回的消息基础数据
     * @param msgcode - 消息响应状态码
     */
    private onGetMailData(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        if (msgcode === com.snake.socket.MessageCode.SYS_NORMAL) {
            var msgBody: com.snake.socket.SC_MAIL_LIST = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_MAIL_LIST);
            if (msgBody && msgBody.mail) {
                // 计算未读邮件数量
                const unreadCount = msgBody.mail.filter(mail => !mail.read).length;

                // 更新未读邮件数量显示
                this.updateUnreadMailCount(unreadCount);

                // 如果有未读邮件，且是本次游戏启动的第一次提醒，显示邮件提醒确认框
                if (unreadCount > 0 && !MainScene.hasShownMailAlertThisSession) {
                    MainScene.hasShownMailAlertThisSession = true;
                    this.showUnreadMailAlert(unreadCount);
                }
            }
        }
    }

    /**
     * 更新未读邮件数量显示
     * @param unreadCount - 未读邮件数量
     */
    private updateUnreadMailCount(unreadCount: number): void {
        // 更新未读邮件数量显示
        if (unreadCount > 0) {
            // 显示红点图标
            this.img_mailRed.visible = true;

            // 根据未读邮件数量选择不同的红点图标
            if (unreadCount < 10) {
                this.img_mailRed.skin = "res/common/comm/img_red1.png";
            } else {
                this.img_mailRed.skin = "res/common/comm/img_red2.png";
            }

            // 显示未读邮件数量
            this.tf_mailNum.visible = true;
            // 如果未读邮件数量大于99，最多显示99
            this.tf_mailNum.text = unreadCount > 99 ? "99" : unreadCount.toString();
        } else {
            // 没有未读邮件，隐藏红点图标和数量显示
            this.img_mailRed.visible = false;
            this.tf_mailNum.visible = false;
        }
    }

    /**
     * 显示未读邮件提醒确认框
     * @param unreadCount - 未读邮件数量
     */
    private showUnreadMailAlert(unreadCount: number): void {
        // 创建提示文本
        const tipText = GameLanguageMgr.getLanguage(83, unreadCount);

        // 显示确认框
        AlertManager.AlertByType(
            AlertType.BASEALERTVIEW,
            tipText,
            AlertType.YES,
            Laya.Handler.create(this, () => {
                // 如果用户点击确认，打开邮件页面并自动打开第一封未读邮件
                // SceneManager.setCurrentScene(SceneType.M_SCENE_MAIL, true);
                ModuleManager.intance.openModule(ModuleName.MailDialog);
            })
        );
    }

