    private setOnlineNum(): void {
        // 使用API接口获取在线人数
        const apiUrl = getServer() + "/statistics/get-online-total";
        HttpCmd.requestGet(apiUrl, {}, false)
            .then((response: any) => {
                if (response && response.code === 200 && response.data !== undefined) {
                    console.log("获取在线人数:", response);
                    // this.tf_onlineNum.text = GameLanguageMgr.getLanguage(610122, response.data.toString());
                    this.tf_onlineNum.text = response.data.toString();
                } else {
                    const cmdId = com.snake.socket.MessageType.MSG_ONLINE_NUM;
                    HallWebSocket.send(cmdId);
                }
            })
            .catch((error: any) => {
                console.error(error);
                const cmdId = com.snake.socket.MessageType.MSG_ONLINE_NUM;
                HallWebSocket.send(cmdId);
            });
    }

    private onOnlineNum(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            const msgBody: com.snake.socket.SC_ONLINE_NUM = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_ONLINE_NUM);
            let onlineNum = Number(msgBody.num);
            // 生成40-60之间的随机数
            const randomNum = Math.floor(Math.random() * 21) + 40;
            // 将随机数加到在线人数上
            onlineNum += randomNum;

            // this.tf_onlineNum.text = GameLanguageMgr.getLanguage(610122, onlineNum.toString());
            this.tf_onlineNum.text = onlineNum.toString();

        }
    }

