    private checkRoomInviteParams(): boolean {
        const urlParams = new URLSearchParams(window.location.search);
        const room = urlParams.get('room');
        const clubRoom = urlParams.get('clubroom');

        // 检查是否有room参数
        if (room) {
            try {
                // 尝试解析JSON格式的room参数
                var _room = DESTool.decodeStr(room);//base64解密
                const roomInfo = JSON.parse(decodeURIComponent(_room));
                console.log("收到房间邀请参数，打开JoinRoomDialog", roomInfo);
                if (roomInfo.target) {
                    var roomVo: RoomVo = new RoomVo();

                    roomVo.arenaType = roomInfo.arenaType; //比赛模式
                    roomVo.pvpRoomIndex = roomInfo.tabIndex;
                    roomVo.pvpTokenIndex = roomInfo.tokenIndex;
                    roomVo.ticketAmount = roomInfo.ticketAmount;
                    roomVo.target = roomInfo.target;//邀请自己的人
                    roomVo.lockToken = true;
                    ModuleManager.intance.openModule(ModuleName.CreateRoomDialog, roomVo);
                } else {
                    ModuleManager.intance.openModule(ModuleName.JoinRoomDialog, [0, 0]);
                }
                // 打开JoinRoomDialog并传入参数 - 使用[0, 0]作为参数，实际参数将从URL获取

                // URL参数的清除逻辑已移到JoinRoomDialog.setOpenData中
                return true;
            } catch (error) {
                console.error("解析房间邀请参数失败:", error);
            }
        }

        // 检查是否有clubroom参数
        if (clubRoom) {
            try {
                // 尝试解析JSON格式的clubroom参数
                const clubRoomInfo: RoomVo = JSON.parse(decodeURIComponent(clubRoom));
                console.log("收到俱乐部房间邀请参数，打开JoinClubRoomDialog", clubRoomInfo);

                // 移除俱乐部ID，只保留房间信息
                const roomInfoWithoutClubId = clubRoomInfo.club;
                // clubRoomInfo.delete("club");
                // 检查房间是否已过期
                const expiryTimestamp = Number(clubRoomInfo.endTime); // 获取到期时间戳
                const currentTime = Date.now();
                // 获取当前的 URL
                const currentUrl = new URL(window.location.href);

                // 解析 URL 参数
                const params = currentUrl.searchParams;

                if (currentTime > expiryTimestamp) {
                    // console.log("房间已过期，不打开JoinClubRoomDialog");
                    NoticeMgr.notice(GameLanguageMgr.getLanguage(94));
                    // 只删除clubroom参数，保留其他参数
                    currentUrl.searchParams.delete('clubroom');
                    // 更新URL，不改变其他参数
                    window.history.replaceState({}, document.title, currentUrl.toString());
                    return true;
                }

                // 检查俱乐部ID是否匹配
                // 获取当前玩家的俱乐部ID
                const playerClubId = GlobalDataManager.playerDto.club;
                // 获取邀请链接中的俱乐部ID（假设在数组的最后一个位置）
                const inviteClubId = roomInfoWithoutClubId;

                // 如果俱乐部ID匹配，才打开JoinClubRoomDialog
                if (playerClubId === inviteClubId) {
                    // 打开JoinClubRoomDialog并传入参数
                    ModuleManager.intance.openModule(ModuleName.JoinClubRoomDialog, clubRoomInfo);

                    return true;
                } else {
                    NoticeMgr.notice(GameLanguageMgr.getLanguage(93)); //暂未开放
                    // 只删除clubroom参数，保留其他参数
                    currentUrl.searchParams.delete('clubroom');
                    // 更新URL，不改变其他参数
                    window.history.replaceState({}, document.title, currentUrl.toString());
                }
            } catch (error) {
                console.error("解析俱乐部房间邀请参数失败:", error);
            }
        }

        return false;
    }

