import { MailRewardListItemBase } from "./MailRewardListItem.generated";
import { ItemItem } from "../../data/sheetItem/item/ItemItem";
import SheetDataManager from "../../global/SheetDataManager";
import GameResourceManager from "../../common/GameResourceManager";
const { regClass } = Laya;

@regClass('cVATpJOeQgeVQnaU8vno+g==')
export class MailRewardListItem extends MailRewardListItemBase {
    private rewardItem: any;

    public constructor() {
        super();
    }
    onEnable(): void {
        this.on(Laya.Event.CLICK, this, this.toRead);
    }

    public set dataSource(value: any) {
        super.dataSource = value;
        this.rewardItem = value as any;
        if (!this.rewardItem) {
            this.visible = false;
            return;
        }

        const itemItem: ItemItem = SheetDataManager.m_dicItems.get(this.rewardItem.itemId);
        if (!itemItem) {
            this.visible = false;
            return;
        }
        if (itemItem.icon < 1000) {
            //蛇
            this.img_icon.skin = GameResourceManager.getSnakeIcon(itemItem.icon);
        } else {
            this.img_icon.skin = GameResourceManager.getItemIcon(itemItem);
        }
        this.tf_num.text = `x${this.rewardItem.num}`;
    }

    private toRead() {}
}
