const { regClass } = Laya;
import AlertManager from "../../common/AlertManager";
import { AlertType } from "../../common/AlertType";
import GameLanguageMgr from "../../common/GameLanguageMgr";
import GameResourceManager from "../../common/GameResourceManager";
import { ModuleManager } from "../../common/ModuleManager";
import { TokenData } from "../../data/dto/TokenData";
import EthereumManager from "../../global/contract/EthereumManager";
import Signal from "../../global/event/Signal";
import { ModuleName } from "../../global/ModuleName";
import HallWebSocket from "../../network/HallWebSocket";
import { com } from "../../network/pb/socket";
import { ComUtil } from "../../utils/ComUtil";
import { NumberUtil } from "../../utils/NumberUtil";
import { SocketDataUtil } from "../../utils/SocketDataUtil";
import { AssetItemBase } from "./AssetItem.generated";

@regClass('oDHEPtPLT9SboHGJIeNVbA==')
export class AssetItem extends AssetItemBase {
    private data: TokenData;
    public constructor() {
        super();
    }

    public set dataSource(data: any) {
        super.dataSource = data;
        this.setData(data);
        this.addEvent();
        // 获取当前项在列表中的索引位置，用于控制背景显示
        const index = (this.parent?.parent as Laya.List)?.array?.indexOf(data) ?? 0;

        // 奇数行显示背景，偶数行不显示
        this.img_bg.skin = index % 2 === 1 ? "res/asset/assetNew/img_di1.png" : "res/asset/assetNew/img_di.png";

    }

    private addEvent() {
        this.btn_deposit.on(Laya.Event.CLICK, this, this.onDeposit);
        this.btn_withdraw.on(Laya.Event.CLICK, this, this.onWithdraw);
    }

    /**
     * 设置货币项目数据
     * @param data
     */
    private setData(data: TokenData) {
        if (data) {
            this.data = data;
            this.tf_coinNum.text = `${NumberUtil.formatTrimZeroDecimal2(data.balance,5)}`;
            this.tf_freeze.text = `${data.frozen}`;
            // data.price = 1.00000000001
            if(data.price < 0.0001){
                this.tf_prize.text = `${NumberUtil.formatCurrencyPrice(data.price)}`;
            }else{
                this.tf_prize.text = `${NumberUtil.formatCurrencyPriceWithZeroCheck(data.price)}`;
            }
            // this.tf_prize.text = `${data.price}`;
            let valuStr = Number(data.valuation).toFixed(2);
            if (valuStr.endsWith("0")) {
                valuStr = Number(data.valuation).toFixed(1);
                if (valuStr.endsWith("0")) {
                    valuStr = Number(data.valuation).toFixed(0);
                }
            }
            this.tf_valu.text = valuStr;
            this.img_coin.skin = GameResourceManager.getCurrencyIcon(data.symbol)
            this.img_coin.visible = true
            this.tf_coin.text = data.symbol;
            if(data.withdraw){
                this.btn_withdraw.visible = true;
            }else{
                this.btn_withdraw.visible = false;
            }
            if(data.recharge){
                this.btn_deposit.visible = true;
            }else{
                this.btn_deposit.visible = false;
            }
        } else {
            this.visible = false;
        }
    }

      /**
     * 处理充值按钮点击事件
     */
    private onDeposit() {
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_CHARGE, this, this.onRequestChargeInfo);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_CHARGE, this, this.onRequestChargeInfo);
        const cmdId = com.snake.socket.MessageType.MSG_CHARGE;
        const symbol = this.data.symbol;
        const requestData = com.snake.socket.CS_CHARGE.fromObject({
            symbol: symbol
        });
        HallWebSocket.send(cmdId, requestData);
    }

         /**
     * 获取充值信息
     */
    public async onRequestChargeInfo(msgBase: com.snake.socket.CMsgBase, msgcode: number) {
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_CHARGE, this, this.onRequestChargeInfo);
        var msgBody: com.snake.socket.SC_CHARGE = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_CHARGE);
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            console.log("SC_CHARGE", msgBody);
            //获取到充值信息
            let data = ComUtil.parseJsonArray(msgBody.chargeInfo);
            let tonConnectUI = EthereumManager.tonConnectUI;
            console.log("tonConnectUI", tonConnectUI);
            let currentChainId:number;
            if (tonConnectUI) {
                currentChainId = 1000239
            }else if(EthereumManager.isTronLogin){
                currentChainId = await EthereumManager.getTronChainId();
            }else{
                currentChainId = await EthereumManager.walletClient.getChainId();
            }
            const matchedItem = data.find(item => Number(item.chainId) === Number(currentChainId));
            if (!matchedItem) {
                let needToChainData = data[0];
                let content = GameLanguageMgr.getLanguage(95,needToChainData.chainName);
                // let content = `暂不支持当前网络进行的充值操作，请切换至${this.needToChainData.chainName}链进行充值`;
                AlertManager.AlertByType(AlertType.BASEALERTVIEW, content, AlertType.YES);
                console.log("未找到匹配的链信息");
                return
            }
            ModuleManager.intance.openModule(ModuleName.DepositDialog, this.data);
        }
    }

    /**
     * 处理提现按钮点击事件
     */
    private onWithdraw() {
        ModuleManager.intance.openModule(ModuleName.WithdrawDialog, this.data);
    }
}
