import MatchModel from "../../modules/match/MatchModel";
import { com } from "../../network/pb/socket";
import Snake from "./Snake";
import SnakeManager from "./SnakeManager";
import FrameSyncManager from "../match/FrameSyncManager";

export default class PvpSnake extends Snake {
    /**
     * @param pnl 父容器
     * @param pos 初始位置
     * @param dir 初始方向（可选，默认向右）
     * @param len 蛇的骨骼数量（可选）
     * @param tag 节点标签（可选）
     */
    constructor(pnl: Laya.Sprite, roomPlayerDto: com.snake.socket.PlayerObject) {
        super(pnl, roomPlayerDto);
    }

    lastSendFrame: number = -1;
    rorateReadySend() {
        if (this.isSelf && this.viewSnake && this.lastSendFrame != FrameSyncManager.currentFrame) {
            this.rotateSend();
            this.lastSendFrame = FrameSyncManager.currentFrame;
        }
    }

    /**
     * 设置目标方向（外部调用时传入新的方向向量）
     */
    public rotateSend(): void {
        this.viewSnake.rotateSend();
    }

    override goMatchEnd() {
        SnakeManager.getInstance().removeSnake(this.tag.roleId);
        MatchModel.onMockMatchEnd();
    }
    /**
     * 同步显示层
     */
    adjustVisualState() {
        this.viewSnake.adjustVisualState(this.logicSnake);
    }
    // 添加其他更新方法
    protected updateOther(): void {}
}
