import { Collision } from "../collision/Collision";
import DebugLayer from "../DebugLayer";
import FoodManager from "../food/FoodManager";
import FrameSyncManager from "./FrameSyncManager";
import SnakeManager from "../snake/SnakeManager";
import GameSetting from "../../global/GameSetting";
import MapManager from "../map/MapManager";
import RoomWebSocket from "../../network/RoomWebSocket";
import MatchModel from "../../modules/match/MatchModel";
import Signal from "../../global/event/Signal";
import { SocketEvent } from "../../global/event/SocketEvent";

class GameControl {
    private static instance: GameControl | null = null;

    public static getInstance(): GameControl {
        if (!GameControl.instance) {
            GameControl.instance = new GameControl();
        }
        return GameControl.instance;
    }

    /**
     * 1.初始化蛇、食物等本地数据
     */
    init(gameLayer: Laya.Sprite = null) {
        if (!gameLayer) {
            throw new Error("gameLayer Must Be Not Null");
        }

        SnakeManager.getInstance().init();
        FoodManager.init();

        // 创建蛇层并设置 zOrder
        const snakeLayer = SnakeManager.getInstance().container;
        const foodLayer = FoodManager.container;
        const debugLayer = new Laya.Sprite();

        gameLayer.addChild(foodLayer);
        gameLayer.addChild(snakeLayer);
        gameLayer.addChild(debugLayer);

        debugLayer.addChild(DebugLayer.getInstance());
        // FoodManager.init();
        this.onConnectRoom();
    }

    /**
     * 2.连接房间 发起对时、请求进入房间
     */
    public onConnectRoom(): void {
        if (MatchModel.roomDto && MatchModel.roomDto.isWatch) {
            Signal.event(SocketEvent.EVENT_ROOM_START_REQUEST_TIME);
        } else {
            RoomWebSocket.initSocket();
        }
    }
    /**
     * 3.拉倒数据，刷新
     */
    createData() {
        SnakeManager.getInstance().createSnakes();
        FoodManager.createFoodsByData();
    }
    /**
     * 4.开始游戏
     */
    startGame(isFirst:boolean) {
        if (MatchModel.matchDto.watch && isFirst) {
            var otherSnake = SnakeManager.getInstance().getFirstSnake();
            MapManager.setOtherHero(otherSnake);
        } else {
            var snake = SnakeManager.getInstance().selfSnake;
            MapManager.setCurrentHero(snake);
        }
        // 开始帧同步
        FrameSyncManager.start();
    }

    clearTimer(): void {
        FrameSyncManager.stop();
    }

    endTimer(): void {
        FrameSyncManager.end();
    }

    public update(frame: number, isLogicSnake: boolean, hasConfirmed: boolean, needMove: boolean = true): void {
        // console.log(Quick.GetLogTime, "update: ", frame, isLogicSnake, hasConfirmed);
        SnakeManager.getInstance().updateSnakes(Laya.timer.delta, isLogicSnake, hasConfirmed, needMove);
        if (!isLogicSnake) {
            MapManager.moveGameWindow();
            // MapManager.move(SnakeManager.getInstance().getSelfSnakePos(isLogicSnake));
            // 调试绘制
            if (GameSetting.needDraw) {
                const debugLayer = DebugLayer.getInstance();
                if (debugLayer) {
                    debugLayer.clearDraw();
                    //碰撞体绘制
                    // const allCollidables = Collision.getInstance(null).getAllCollidables();
                    // debugLayer.updateCollidables(allCollidables);
                    // debugLayer.draw();

                    Collision.getInstance(null).drawDebug(debugLayer.graphics); //四叉树绘制
                }
            }
        }
    }
    restoreData() {
        SnakeManager.getInstance().restoreSnakes();
        FoodManager.restoreFoods();
    }

    clear() {
        this.clearTimer();
    }
}
export default GameControl.getInstance();
