import Signal from "../global/event/Signal";
import { Quick } from "../utils/Quick";
import { HallMessageHandle } from "./HallMessageHandle";
import { com } from "./pb/socket";
import { SocketDataUtil } from "../utils/SocketDataUtil";
import { SocketEvent } from "../global/event/SocketEvent";
import GameSetting from "../global/GameSetting";
import GlobalDataManager from "../global/GlobalDataManager";
import EthereumManager from "../global/contract/EthereumManager";

class HallWebSocket {
    private _socket: Laya.Socket = null;
    connected: boolean;

    wsUrl: string = getWSServer();
    token: string;
    private isFirstConnection: boolean = true;

    // 字节缓存
    private _byte: Laya.Byte;
    // 包头长度
    private _headerLength = 4;
    // 当前正在处理的数据包长度
    private _packetLength: number = -1;

    // handle: HallMessageHandle;

    private static _instance: HallWebSocket;
    public static getInstance(): HallWebSocket {
        if (HallWebSocket._instance == null) {
            HallWebSocket._instance = new HallWebSocket();
        }
        return HallWebSocket._instance;
    }

    public constructor() {
        new HallMessageHandle();
        this._byte = new Laya.Byte();
        this._byte.endian = "bigEndian"; // "littleEndian";根据实际协议调整
        this._socket = new Laya.Socket();
        this._socket.on(Laya.Event.OPEN, this, this.onSocketOpen);
        this._socket.on(Laya.Event.CLOSE, this, this.onSocketClose);
        this._socket.on(Laya.Event.MESSAGE, this, this.onMessageReveived);
        this._socket.on(Laya.Event.ERROR, this, this.onSocketError);

        // 注册处理大厅地址响应的消息
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_REQUEST_HALL_ADDR, this, this.onHallAddrResponse);
    }

    /**
     * 连接服务器
     * @param serverAddress 服务器地址
     */
    public connect() {
        // console.log(Quick.GetLogTime, "[HallWebSocket] Try to connect url = " + this.wsUrl, EthereumManager.walletAddress);
        if (this.connected) {
            return; //连接了，不去连接
        }

        this.connectWebSocket();
        this.emit(SocketEvent.EVENT_HALL_SHOW_TIP_DELAY);
    }

    connectWebSocket() {
        console.log(Quick.GetLogTime, "[HallWebSocket] Try to connect url = " + this.wsUrl, EthereumManager.walletAddress);
        
        this._socket.connectByUrl(this.wsUrl);
    }

    /* 当连接到服务器 */
    public onSocketOpen() {
        this.connected = true;
        console.log(Quick.GetLogTime, "[HallWebSocket] ----onOpen------------> connected");

        // if (GameSetting.vType == 0) {
        //     // 如果是第一次连接，发送请求获取大厅地址
        //     if (this.isFirstConnection && EthereumManager.walletAddress) {
        //         this.requestHallAddr();
        //         this.isFirstConnection = false;
        //         // 不触发EVENT_HALL_SOCKET_OPEN事件，等待获取到大厅地址后再触发
        //         console.log(Quick.GetLogTime, "[HallWebSocket] Requesting hall address before login");
        //     } else {
        //         // 不是首次连接或没有钱包地址，正常触发连接成功事件
        //         this.emit(SocketEvent.EVENT_HALL_SOCKET_OPEN);
        //     }
        // } else {
            this.emit(SocketEvent.EVENT_HALL_SOCKET_OPEN);
        // }
    }

    /**
     * 请求大厅地址
     */
    private requestHallAddr() {
        console.log(Quick.GetLogTime, "[HallWebSocket] Requesting hall address for wallet: " + EthereumManager.walletAddress);

        // 创建请求消息
        var requestData = com.snake.socket.CS_REQUEST_HALL_ADDR.fromObject({
            address: EthereumManager.walletAddress
        });

        // 发送请求
        this.send(com.snake.socket.MessageType.MSG_REQUEST_HALL_ADDR, requestData);
    }

    /**
     * 处理大厅地址响应
     */
    private onHallAddrResponse(msgBase: com.snake.socket.CMsgBase, msgcode: number) {
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            var msgBody: com.snake.socket.SC_REQUEST_HALL_ADDR = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_REQUEST_HALL_ADDR);
            if (msgBody && msgBody.hallAddr) {
                console.log(Quick.GetLogTime, "[HallWebSocket] Received hall address: " + msgBody.hallAddr);

                // 保存当前连接状态
                var wasConnected = this.connected;

                // 关闭当前连接
                this.close();

                // 更新服务器地址
                this.wsUrl = msgBody.hallAddr;
                console.log(Quick.GetLogTime, "[HallWebSocket] Switching to new hall address: " + this.wsUrl);

                // 重新连接到新地址
                this.isFirstConnection = false; // 确保不会再次请求
                this.connectWebSocket();

                // 下次连接成功后会触发EVENT_HALL_SOCKET_OPEN事件，从而启动登录流程
            }
        } else {
            // 如果获取大厅地址失败，也要触发连接成功事件，让流程继续
            console.log(Quick.GetLogTime, "[HallWebSocket] Failed to get hall address, continue with current connection");
            this.emit(SocketEvent.EVENT_HALL_SOCKET_OPEN);
        }
    }

    /* 当出现错误时 */
    public onSocketError(evt: any) {
        this.connected = false;
        console.log(Quick.GetLogTime, "[HallWebSocket] ----onError------------>", evt);
        this.emit(SocketEvent.EVENT_HALL_SOCKET_ERROR);
    }

    /* 当连接断开时 */
    public onSocketClose() {
        this.connected = false;
        console.log(Quick.GetLogTime, "[HallWebSocket] ----onClose------------>", this._socket);
        this.emit(SocketEvent.EVENT_HALL_SOCKET_CLOSE);
    }

    /* 关闭websocket */
    public close() {
        this.connected = false;
        console.log(Quick.GetLogTime, "[HallWebSocket] ----WS:close");
        if (this._socket) {
            this._socket.close();
        }

        // 移除大厅地址响应的监听
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_REQUEST_HALL_ADDR, this, this.onHallAddrResponse);
    }

    public clearAll() {
        Laya.timer.clearAll(this);
        this.close();
        this.emit(SocketEvent.EVENT_HALL_STOP_HEART);
    }

    public send(messageType: number, body?: any, showLoading: boolean = true) {
        if (this.connected) {
            var byteData: Uint8Array = body ? body.serializeBinary() : null;
            if (messageType != com.snake.socket.MessageType.MSG_HEART_BEAT) {
                console.log(Quick.GetLogTime, "[HallWebSocket]  ------>>>>>>>> SEND CMD:" + messageType, body ? body.toObject() : null);
            }
            var data = SocketDataUtil.encodeMessage(messageType, byteData, "");
            this._socket.send(data.buffer);
        } else {
            console.log(Quick.GetLogTime, "[HallWebSocket]  ------>>>>>>>> SENDE RROR CMD:" + messageType, body ? body.toObject() : null);
        }
    }

    /**
     * 收到命令
     * @param msg
     */
    private onMessageReveived(msg: any = null): void {
        console.log(Quick.GetLogTime, "[HallWebSocket]: onMessage", msg.byteLength);
        if (!(msg instanceof ArrayBuffer)) {
            console.warn(Quick.GetLogTime, "[HallWebSocket]: no ArrayBuffer data", msg);
            return;
        }

        // 将新数据追加到缓存
        let newData = new Uint8Array(msg);
        this._byte.writeArrayBuffer(newData.buffer);
        this._byte.pos = 0;

        // 处理数据包
        while (this._byte.bytesAvailable > 0) {
            if (this._packetLength === -1) {
                // 读取包头获取包体长度
                if (this._byte.bytesAvailable >= this._headerLength) {
                    this._packetLength = this._byte.getUint32();
                } else {
                    break; // 数据不足，等待更多数据
                }
            }

            // 检查是否有完整的包体
            if (this._byte.bytesAvailable >= this._packetLength) {
                // 读取包体数据
                // let packetData = this._byte.readArrayBuffer(this._packetLength);
                let packetData = this._byte.readUint8Array(this._headerLength, this._packetLength);
                this.processPacket(packetData);
                this._packetLength = -1; // 重置准备读取下一个包头
            } else {
                break; // 数据不足，等待更多数据
            }
        }

        // 清理已处理的数据
        if (this._byte.pos > 0) {
            let remaining = this._byte.bytesAvailable;
            if (remaining > 0) {
                let temp = this._byte.readUint8Array(0, remaining);
                this._byte.clear();
                this._byte.writeArrayBuffer(temp.buffer);
            } else {
                this._byte.clear();
            }
        }
    }

    /**
     * 处理完整的数据包
     * @param data 数据包内容(Uint8Array)
     */
    private processPacket(data: Uint8Array): void {
        try {
            var messageBase = SocketDataUtil.decodeMessage(data);
            // var messageBase = com.snake.socket.CMsgBase.deserializeBinary(data);
            var msgtype = messageBase.msghead.msgtype;
            if (msgtype != com.snake.socket.MessageType.MSG_HEART_BEAT) {
                // if (GameSetting.Debug == 2) {
                //     // var msgBody: com.snake.socket.SC_USER_LOGIN = SocketDataUtil.getMsgBody(messageBase);
                //     // console.log(Quick.GetLogTime, "[HallWebSocket]: onMessage", msgtype.toString(), msgBody);
                // } else if (GameSetting.Debug == 1) {
                console.log(Quick.GetLogTime, "[HallWebSocket]: onMessage", msgtype.toString(), messageBase);
                // }
            }

            this.emitter(msgtype, messageBase);
        } catch (e) {
            console.log(Quick.GetLogTime, "[HallWebSocket] onSocketError e:" + e);
        }
    }

    emitter(msgtype: number, messageBase: com.snake.socket.CMsgBase) {
        var msgcode = messageBase.msghead.msgcode;
        if (msgcode != com.snake.socket.MessageCode.SYS_NORMAL) {
            this.emit(SocketEvent.EVENT_GLOBAL_ERROR_CODE, msgcode);
        }

        this.emit("msg_" + msgtype, messageBase, msgcode);
    }

    /**
     * 触发事件
     * @param event 事件名称
     * @param args 参数
     */
    private emit(event: string, ...args: any[]): void {
        Signal.event(event, args);
    }
}

export default HallWebSocket.getInstance();
