import { ModuleManager } from "../../common/ModuleManager";
import { MailVo } from "../../data/vo/pack/MailVo";
import { ModuleName } from "../../global/ModuleName";
import { TimeUtil } from "../../utils/TimeUtil";
import { MillListItemBase } from "./MillListItem.generated";
const { regClass } = Laya;

@regClass('3h2PsGTIQV6ilXcpYeJ0cQ==')
export class MillListItem extends MillListItemBase {
    public mailVo: MailVo;

    public constructor() {
        super();
    }

    onEnable(): void {
        this.on(Laya.Event.CLICK, this, this.onOpenMailClick);
    }

    public set dataSource(value: any) {
        super.dataSource = value;
        this.mailVo = value as any;
        if (!this.mailVo) {
            return;
        }
        this.tf_title.text = this.mailVo.title;
        this.tf_from.text = this.mailVo.sendName;
        this.img_red.visible = !this.mailVo.read;
        this.tf_time.text = TimeUtil.formatTimeAgoFromTimestamp(this.mailVo.sendTime);
        this.img_bg.skin = this.mailVo.read ? "res/mail/newMail/img_kuang1.png" : "res/mail/newMail/img_kuang.png";
        this.img_box.skin = this.mailVo.read ? "res/mail/newMail/img_tu2.png" : "res/mail/newMail/img_tu1.png";
    }

    private onOpenMailClick(): void {
        ModuleManager.intance.openModule(ModuleName.MailDetailDialog, this.mailVo);
        // MailDetailDialog
    }

}
