const { regClass } = Laya;
import GameLanguageMgr from "../../common/GameLanguageMgr";
import GameResourceManager from "../../common/GameResourceManager";
import { ModuleManager } from "../../common/ModuleManager";
import { RaceVo } from "../../data/vo/pack/RaceVo";
import GameSetting from "../../global/GameSetting";
import { ModuleName } from "../../global/ModuleName";
import AssetManager from "../../manager/AssetManager";
import { TimeUtil } from "../../utils/TimeUtil";
import { MatchTournamentListItemBase } from "./MatchTournamentListItem.generated";

@regClass('w6kO36/RTAS3RWabluZDow==')
export class MatchTournamentListItem extends MatchTournamentListItemBase {
    private raceVo: RaceVo;
    private type = 0;
    private tipLan = 0;
    private restTime = 0;

    public constructor() {
        super();
    }
    onEnable(): void {
        this.on(Laya.Event.CLICK, this, this.onPlaying);
    }

    public set dataSource(value: any) {
        super.dataSource = value;
        if (!value) {
            return;
        }
        this.raceVo = value;

        var now = new Date().getTime();
        this.tipLan = 0;
        this.restTime = 0;
        if (now < this.raceVo.raceDto.signBeginTime) {
            console.log("报名时间未到"); //报名没开始，就显示报名开始时间
            this.type = 1;
            this.tf_time.text = TimeUtil.formatTimeStampWithWeek(this.raceVo.raceDto.signBeginTime);
            // this.tf_time.text =
            //     TimeUtil.formatTimeStamp(this.raceVo.raceDto.signBeginTime, "MT-DD HH:MM:SS") +
            //     " ~ " +
            //     TimeUtil.formatTimeStamp(this.raceVo.raceDto.signEndTime, "MT-DD HH:MM:SS");

            // 计算剩余时间（秒）
            this.tipLan = 610108; // "离报名开始时间还有: {0}",
            this.restTime = this.raceVo.raceDto.signBeginTime - now;

            // this.tf_reduceTime.text = GameLanguageMgr.getLanguage(
            //     610108,

            //     TimeUtil.getRestTime(Math.floor(this.raceVo.raceDto.signBeginTime / 1000))
            // ); // "离报名开始时间还有: {0}",
            this.btn_playing.label = GameLanguageMgr.getLanguage(610109); //即将开始
            this.btn_playing.disabled = true;
        } else if (now < this.raceVo.raceDto.signEndTime) {
            this.type = 2;
            console.log("可以报名"); //报名开始了，就显示报名结束时间
            this.tf_time.text = TimeUtil.formatTimeStampWithWeek(this.raceVo.raceDto.signEndTime);
            // this.tf_time.text =
            //     TimeUtil.formatTimeStamp(this.raceVo.raceDto.signBeginTime, "MT-DD HH:MM:SS") +
            //     " ~ " +
            //     TimeUtil.formatTimeStamp(this.raceVo.raceDto.signEndTime, "MT-DD HH:MM:SS");

            this.tipLan = 610110; //离报名截止时间还有: {0}
            this.restTime = this.raceVo.raceDto.signEndTime - now;

            // this.tf_reduceTime.text = GameLanguageMgr.getLanguage(610110, TimeUtil.getRestTime(Math.floor(this.raceVo.raceDto.signEndTime / 1000))); //离报名截止时间还有: {0}
            if (this.raceVo.isSign) {
                this.btn_playing.label = GameLanguageMgr.getUILang("REGISTERED");
            } else {
                this.btn_playing.label = GameLanguageMgr.getUILang("REGISTER");
            }

            this.btn_playing.disabled = false;
        } else if (now < this.raceVo.raceDto.beginTime) {
            this.type = 3;
            console.log("游戏时间未到"); //报名结束了  比赛未开始 显示比赛开始时间
            this.tf_time.text = TimeUtil.formatTimeStampWithWeek(this.raceVo.raceDto.beginTime);
            // this.tf_time.text =
            //     TimeUtil.formatTimeStamp(this.raceVo.raceDto.beginTime, "MT-DD HH:MM:SS") +
            //     " ~ " +
            //     TimeUtil.formatTimeStamp(this.raceVo.raceDto.endTime, "MT-DD HH:MM:SS");
            this.tipLan = 610111; //离比赛开始时间还有: {0}
            this.restTime = this.raceVo.raceDto.beginTime - now;

            // this.tf_reduceTime.text = GameLanguageMgr.getLanguage(610111, TimeUtil.getRestTime(Math.floor(this.raceVo.raceDto.beginTime / 1000))); //离比赛开始时间还有: {0}
            this.btn_playing.label = GameLanguageMgr.getUILang("PLAYING");
            this.btn_playing.disabled = true;
        } else if (now < this.raceVo.raceDto.endTime) {
            this.type = 4;
            console.log("可以比赛"); //游戏开始了，就显示游戏结束时间

            this.tf_time.text = TimeUtil.formatTimeStampWithWeek(this.raceVo.raceDto.endTime);
            // this.tf_time.text =
            //     TimeUtil.formatTimeStamp(this.raceVo.raceDto.beginTime, "MT-DD HH:MM:SS") +
            //     " ~ " +
            //     TimeUtil.formatTimeStamp(this.raceVo.raceDto.endTime, "MT-DD HH:MM:SS");
            this.tipLan = 610112; //离比赛结束时间还有: {0}
            this.restTime = this.raceVo.raceDto.endTime - now;
            // this.tf_reduceTime.text = GameLanguageMgr.getLanguage(610112, TimeUtil.getRestTime(Math.floor(this.raceVo.raceDto.endTime / 1000))); //离比赛结束时间还有: {0}
            this.btn_playing.label = GameLanguageMgr.getUILang("PLAYING");
            this.btn_playing.disabled = false;
        } else {
            this.type = 5;
            console.log("比赛结束");
            this.tf_time.text = "";
            this.tf_reduceTime.text = GameLanguageMgr.getLanguage(610113, TimeUtil.formatTimeStamp(this.raceVo.raceDto.endTime, "MT-DD HH:MM:SS")); //比赛结束时间: {0}
            this.btn_playing.label = GameLanguageMgr.getUILang("ENDED");
            this.btn_playing.disabled = false;
        }

        if (GameSetting.Debug == 2) {
            this.tf_time.text += "-" + this.raceVo.raceDto.name;
        }

        if (this.tipLan > 0) {
            this.setReduceTimeTxt();
            Laya.timer.loop(1000, this, this.setReduceTimeTxt);
        } else {
            Laya.timer.clear(this, this.setReduceTimeTxt);
        }

        var poolType = this.raceVo.getPoolType();

        var tokenData = AssetManager.getTokenData().find((item) => item.symbolId == poolType);
        if (tokenData) {
            this.img_token.skin = GameResourceManager.getCurrencyIcon(tokenData.symbol);
        } else {
            console.log("没有找到token数据");
            this.img_token.skin = null;
        }
        this.tf_token.text = String(this.raceVo.getPoolReward());
        this.tf_playerNum.text = this.raceVo.raceDto.num + "";

        if (this.type < 3) {
            if (this.raceVo.raceDto.feeNum) {
                //注册阶段显示
                let tokenData = AssetManager.getTokenDataBySyId(Number(this.raceVo.raceDto.feeId));
                if (tokenData) {
                    this.tf_ticketNum.text = `${this.raceVo.raceDto.feeNum} ${tokenData.symbol}`;
                } else {
                    this.tf_ticketNum.text = `${this.raceVo.raceDto.feeNum}`;
                }
                this.img_playerNum.y = 419;
            } else {
                this.tf_ticketNum.text = "";
                this.img_playerNum.y = 435;
            }
        } else {
            this.tf_ticketNum.text = "";
            this.img_playerNum.y = 435;
        }
    }

    private setReduceTimeTxt() {
        this.tf_reduceTime.text = GameLanguageMgr.getLanguage(this.tipLan, TimeUtil.getReduceTime(Math.floor(this.restTime / 1000))); //离比赛结束时间还有: {0}
        this.restTime -= 1000;
        if (this.restTime < 0) {
            this.tf_reduceTime.text = GameLanguageMgr.getLanguage(this.tipLan, TimeUtil.getReduceTime(0)); //离比赛结束时间还有: {0}

            Laya.timer.clear(this, this.setReduceTimeTxt);
        }
    }

    private onPlaying(): void {
        if (this.raceVo && !this.btn_playing.disabled) {
            // if (this.type == 2) {
            //     //注册
            //     const cmdId = com.snake.socket.MessageType.MSG_RACE_SIGN;

            //     const requestData = com.snake.socket.CS_RACE_SIGN.fromObject({
            //         raceId: this.raceVo.raceDto.id
            //     });

            //     HallWebSocket.send(cmdId, requestData);
            // } else if (this.type == 4) {
            //打比赛
            ModuleManager.intance.openModule(ModuleName.MatchTournamentView, [this.raceVo]);
            // }
        }
    }

    onDisable(): void {
        Laya.timer.clearAll(this);
    }
}
