import GameLanguageMgr from "../../common/GameLanguageMgr";
import GameResourceManager from "../../common/GameResourceManager";
import { ItemItem } from "../../data/sheetItem/item/ItemItem";
import SheetDataManager from "../../global/SheetDataManager";
import { ClubPropListItemBase } from "./ClubPropListItem.generated";

const { regClass } = Laya;

@regClass('S77mjsF1RLqmnYyXCTSkVw==')
export class ClubPropListItem extends ClubPropListItemBase {
    isAddEvent: boolean;
    public set dataSource(value: any) {
        super.dataSource = value;
        if (value) {
            console.log("ClubPropListItem", value)
            const itemItem: ItemItem = SheetDataManager.m_dicItems.get(value.id);
            this.img_icon.skin = GameResourceManager.getItemIcon(itemItem);
            this.tf_data.text = `${GameLanguageMgr.getLanguage(itemItem.name)}X${value.count}`
        }
    }

    onDisable(): void {
    }

    private onChange(isSelect: boolean) {
        if (isSelect) {
            this.selectImg.visible = true;
            this.tf_data.color = "#ffffff";
        } else {
            this.tf_data.color = "#357cc0";
            this.selectImg.visible = false;
        }
    }
}