// IDGen.ts
/**
 * ID生成器
 */
export class IDGen {
  private static seq: number = 1; // ID序列

  /**
   * 生成唯一ID
   * @returns 新ID
   */
  static genID(): number {
    return IDGen.seq++;
  }
}
