export class Dictionary {
    public SERIALIZATION_NUM: number;
    private _cachedValues: any[] = [];
    private _dirty = true;
    private _needCache = false;
    public constructor(needCache: boolean = false) {
        this.SERIALIZATION_NUM = new Date().getTime();
        this._needCache = needCache;
    }

    private _map = new Map();
    public get values(): any[] {
        if (this._needCache) {
            if (this._dirty) {
                this._cachedValues = [...this._map.values()];
                this._dirty = false;
            }
            return this._cachedValues;
        } else {
            return [...this._map.values()];
        }
    }

    public get keys(): any[] {
        return [...this._map.keys()];
    }

    public set(key: any, value: any): void {
        this._map.set(key, value);
        this._dirty = true;
    }

    public get(key: any): any {
        return this._map.get(key);
    }

    public remove(key: any): boolean {
        this._dirty = true;
        return this._map.delete(key);
    }

    public clear(): void {
        this._map.clear();
        this._cachedValues.length = 0;
        this._dirty = true;
    }

    public has(key: any): boolean {
        return this._map.has(key);
    }

    get size(): number {
        return this._map.size;
    }

    getValues(): MapIterator<any> {
        return this._map.values(); //获取原map的values
    }
    getMap() {
        return this._map;
    }

    getFirstEntry(): any {
        const iterator = this._map.entries();
        const firstEntry = this._map.size > 0 ? iterator.next().value : undefined;

        if (firstEntry) {
            const [key, value] = firstEntry;
            console.log("First entry:", { key, value });
            return value
        }

        return firstEntry;
    }
}
