import { com } from "../../network/pb/socket";
import { Food } from "./Food";

/**
 * 食物类
 */
export class FoodPool {
    private pool: Food[] = [];

    constructor(private container: Laya.Sprite) {}

    public getFood(foodObject: com.snake.socket.FoodObject, isDie = false): Food {
        let food: Food;
        if (this.pool.length > 0) {
            food = this.pool.pop()!;
            food.reset(this.container, foodObject, isDie);
        } else {
            food = new Food(this.container, foodObject, isDie);
        }
        return food;
    }

    public returnFood(food: Food): void {
        food.resetForPool();
        this.pool.push(food);
    }

    public clear(): void {
        this.pool.forEach((food) => food.destroy());
        this.pool = [];
    }
}
