const { regClass } = Laya;
import { SceneType } from "../../common/baseScene/SceneType";
import GameLanguageMgr from "../../common/GameLanguageMgr";
import { LayerManager } from "../../common/LayerManager";
import SceneManager from "../../common/SceneManager";
import { EnumItemType } from "../../data/enumData/EnumItemType";
import { EnumMatch } from "../../data/enumData/EnumMatch";
import { ItemVo } from "../../data/vo/pack/ItemVo";
import Signal from "../../global/event/Signal";
import GlobalDataManager from "../../global/GlobalDataManager";
import HallWebSocket from "../../network/HallWebSocket";
import { com } from "../../network/pb/socket";
import { Dictionary } from "../../utils/Dictionary";
import { SocketDataUtil } from "../../utils/SocketDataUtil";
import { SettleDialogBase } from "./SettleDialog.generated";
import GameManager from "./GameManager";
import { NumberUtil } from "../../utils/NumberUtil";
import MatchModel from "../match/MatchModel";
import { RoomVo } from "../../data/vo/pack/RoomVo";
import { ModuleManager } from "../../common/ModuleManager";
import { ModuleName } from "../../global/ModuleName";
import RoomWebSocket from "../../network/RoomWebSocket";
import { SocketEvent } from "../../global/event/SocketEvent";
import SoundMgr from "../../common/SoundMgr";

@regClass('JjhIIfhPRp251zGtjLBPmA==')
export class SettleDialog extends SettleDialogBase {
    public m_iLayerType: number;
    public m_iPositionType: number;
    private stars: Laya.Image[] = [];
    allData: any;
    MathType: number = 1;
    isWin:boolean = true;
    needContinue:boolean = false;
    onAwake(): void {
        this.m_iLayerType = LayerManager.M_POP;
        this.m_iPositionType = LayerManager.UP;
    }

    public setOpenData(datas: any) {
        console.log("datas", datas);
        this.allData = datas[1];
        this.MathType = datas[0];
        // 初始化星级显示
        for (let i = 0; i < 3; i++) {
            var star = (this as any)["img_star_" + (i + 1) + "_1"];
            this.stars.push(star);
            star.alpha = 0;
        }
        if (this.MathType == EnumMatch.MATCH_TYPE_PVP || this.MathType == EnumMatch.ARENA_TYPE_TEAM) {
            let playerData = this.allData[1];//对手信息
            let settleData = this.allData[0];//结算信息
            this.setEnemyData(playerData);
            this.setSettleData(settleData);
            if(EnumMatch.arenaType !== EnumMatch.ARENA_TYPE_CUSTOM) {
                Signal.event(SocketEvent.EVENT_ROOM_STOP_HEART)
            }
            // RoomWebSocket.closeConnect()
        } else {
            Signal.event(SocketEvent.EVENT_ROOM_STOP_HEART)
            this.tf_rank.visible = false;
            this.tf_name.text = GameManager.otherPlayerObject.userName;
            this.playerIcon.dataSource = GameManager.otherPlayerObject;
            this.sendAiEnd(GameManager.hitsCount, this.allData[0], this.allData[1]);
        }
    }

    onEnable(): void {
        // this.tf_scoreTx.text = GameLanguageMgr.getLanguage(3005);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_GAME_AI_END, this, this.onAiEnd);
        this.btn_continue.on(Laya.Event.CLICK, this, this.onClickContinue);
        this.btn_close.on(Laya.Event.CLICK, this, this.onClickBackHome);
        this.btn_exit.on(Laya.Event.CLICK, this, this.onClickBackHome);
    }

    private setEnemyData(playerData: any) {
        let enemyData = playerData.players.find((item) => item.roleId != GlobalDataManager.playerDto.pid);
        if (enemyData) {
            this.tf_name.text = enemyData.userName;
            this.playerIcon.dataSource = enemyData;
        }
    }

    private setSettleData(settleData: any) {
        let item = settleData.items;
        let tokens = settleData.token;
        // var dic: Dictionary = new Dictionary();
        var items: ItemVo[] = [];
        var dic: Dictionary = new Dictionary();
        // var itemDtos:ItemDto[] = MatchModel.instance.reward;
        if (item && item.length > 0)
            item.forEach((itemDto) => {
                var itemVo = dic.get(itemDto.itemId);
                if (!itemVo) {
                    itemVo = new ItemVo(itemDto.itemId);
                    itemVo.newAddCnt = itemDto.num;
                    items.push(itemVo);
                    dic.set(itemDto.itemId, itemVo);
                } else {
                    itemVo.newAddCnt = itemVo.newAddCnt + itemDto.num;
                }
            });
        if (tokens && tokens.length > 0) {
            //token 击杀时间，被击杀国家，名字，id，数量
            var value = tokens.split(","); //击杀时间，被击杀国家，名字，id，数量
            var coinType = value[0];
            var coinNum = value[1];

            var m_iId = parseInt(coinType);
            var m_num = parseFloat(coinNum);

            var itemVo: ItemVo = dic.get(m_iId);
            if (!itemVo) {
                itemVo = new ItemVo();
                itemVo.type = EnumItemType.TYPE_TOKEN;
                itemVo.id = m_iId;
                itemVo.newAddCnt = m_num;
                items.push(itemVo);
                dic.set(m_iId, itemVo);
            } else {
                itemVo.newAddCnt = itemVo.newAddCnt + m_num;
            }
            // var itemVo = new ItemVo(EnumConsumeType.TYPE_REWARD_TOKEN);
            // items.push(itemVo);
        }

        // 根据截图中的写法计算列表居中
        var spaceX = this.propList.spaceX;
        var itemRenderW = (this.propList as any).itemTemplate.width;
        var len: number = items.length;
        var listW: number = len * itemRenderW + spaceX * (len - 1);
        this.propList.repeatX = len;
        this.propList.width = listW;
        this.propList.x = ((this.box_outside.width - this.propList.width) >> 1) - 50;
        this.propList.array = items;
        this.propList.visible = true;
        if (items.length > 2) {
            this.img_qbg.width = 500
        } else {
            this.img_qbg.width = 362
        }
        this.tf_tittle.text = settleData.res == true ? "Victory" : "Defeat";
        this.tf_tittle2.text = this.tf_tittle.text;
        this.tf_result.text = settleData.res == true ? "You have defeated" : "You lost to";
        // this.nameBox.width = this.tf_result.width + 14 + 110 + this.tf_name.width;
        // this.img_result.skin = settleData.res == true ? "res/tetris/settle/img_role1.png" : "res/tetris/settle/img_role2.png";
        this.tf_score.text = settleData.score;
        const starCount = NumberUtil.calculateStarCount(settleData.score, 100);

        for (let i = 0; i < 3; i++) {
            const star = this.stars[i];
            if (i < starCount) {
                star.alpha = 1;
            } else {
                star.alpha = 0;
            }
        }
        this.playOpenAnimation()
        this.tf_rank.text = GameLanguageMgr.getLanguage(3004, settleData.mmr);
        this.isWin = settleData.res;
        if (settleData.res) {
            SoundMgr.playSoundByName(SoundMgr.soundName_win);
            this.successBox.visible = true;
            this.failBox.visible = false;
        } else {
            SoundMgr.playSoundByName(SoundMgr.soundName_fail);
            this.successBox.visible = false;
            this.failBox.visible = true;
        }

        if(EnumMatch.arenaType !== EnumMatch.ARENA_TYPE_CUSTOM){
            RoomWebSocket.closeConnect();
        }
    }



    onDisable(): void {
        if(!this.needContinue) {
            RoomWebSocket.closeConnect();
            SoundMgr.playMusicByName(SoundMgr.soundName_bg, ".mp3");
            // SceneManager.setCurrentScene(SceneType.M_SCENE_MAIN);
        }
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_GAME_AI_END, this, this.onAiEnd);
        this.btn_continue.off(Laya.Event.CLICK, this, this.onClickContinue);
        this.btn_close.off(Laya.Event.CLICK, this, this.onClickBackHome);
        this.btn_exit.off(Laya.Event.CLICK, this, this.onClickBackHome);

        // 重置连续消除次数
        GameManager.hitsCount = 0;
        console.log("SettleDialog关闭，重置连续消除次数为0");
    }

    private onClickContinue() {
        if (this.MathType == EnumMatch.MATCH_TYPE_PVP && EnumMatch.arenaType == EnumMatch.ARENA_TYPE_PVP) {
            GlobalDataManager.needToOpenJoinRoom = true;
        } else if (EnumMatch.arenaType == EnumMatch.ARENA_TYPE_CUSTOM) {
            GlobalDataManager.nextTarget = GameManager.otherPlayerObject.roleId;
            if (this.isWin) {
                this.needContinue = true;
                //赢的人继续匹配
                SceneManager.isCloseAll = false;
                // GameManager.otherPlayerObject.roleId = MatchModel.matchDto.otherPlayerObject.roleId;
                // ModuleManager.intance.openModule(ModuleName.MatchReadyView); //增加过渡页
                SceneManager.setCurrentScene(SceneType.M_SCENE_VS, [GlobalDataManager.MathchData,2]); //赢的人继续玩
                // this.close()
            } else {
                // GlobalDataManager.needToOpenPVECustom = true;
                //输的人继续选关
                var pvpRoomIndex = MatchModel.roomDto.pvpRoomIndex;
                if (pvpRoomIndex < 0) {
                    pvpRoomIndex = 0;
                }
                var pvpTokenIndex = MatchModel.roomDto.pvpTokenIndex;
                if (pvpTokenIndex < 0) {
                    pvpTokenIndex = 0;
                }

                var roomVo: RoomVo = new RoomVo();
                var ticketAmount = MatchModel.roomDto.ticketAmount;
                roomVo.pvpRoomIndex = pvpRoomIndex;
                roomVo.pvpTokenIndex = pvpTokenIndex;
                roomVo.arenaType = EnumMatch.ARENA_TYPE_CUSTOM; //自定义模式
                roomVo.ticketAmount = EnumMatch.ARENA_TYPE_CUSTOM; //自定义模式
                roomVo.lockToken = true;
                roomVo.ticketAmount = ticketAmount;
                roomVo.target = GameManager.otherPlayerObject.roleId;
                GlobalDataManager.needToOpenCustomCallBack = Laya.Handler.create(this,()=>{
                    ModuleManager.intance.openModule(ModuleName.CreateRoomDialog, roomVo);
                })
                SceneManager.setCurrentScene(SceneType.M_SCENE_MAIN);
                return
            }
        }else {
            GlobalDataManager.needToOpenPVE = true;
        }
        if(!this.needContinue){
            SceneManager.setCurrentScene(SceneType.M_SCENE_MAIN);
        }
        this.close()
    }


    private onClickBackHome() {
        SceneManager.setCurrentScene(SceneType.M_SCENE_MAIN);
        this.close();
        
    }

    sendAiEnd(count: number, isWin: boolean, score: number): void {
        this.tf_tittle.text = isWin == true ? "Victory" : "Defeat";
        this.tf_tittle2.text = this.tf_tittle.text;
        this.tf_result.text = isWin == true ? "You have defeated" : "You lost to";
        // this.nameBox.width = this.tf_result.width + 14 + 110 + this.tf_name.width;
        // this.img_result.skin = isWin == true ? "res/tetris/settle/img_role1.png" : "res/tetris/settle/img_role2.png";
        this.tf_score.text = `${score}`;
        const starCount = NumberUtil.calculateStarCount(score, 100);

        for (let i = 0; i < 3; i++) {
            const star = this.stars[i];
            if (i < starCount) {
                star.alpha = 1;
            } else {
                star.alpha = 0;
            }
        }
        this.playOpenAnimation()
        GlobalDataManager.playerDto.aiScore = Math.max(GlobalDataManager.playerDto.aiScore, score);
        // this.saveBestRecord(score)
        // this.tf_rank.text = GameLanguageMgr.getLanguage(3004, settleData.mmr);
        if (isWin) {
            SoundMgr.playSoundByName(SoundMgr.soundName_win);
            this.successBox.visible = true;
            this.failBox.visible = false;
        } else {
            SoundMgr.playSoundByName(SoundMgr.soundName_fail);
            this.successBox.visible = false;
            this.failBox.visible = true;
        }
        var cmdId = com.snake.socket.MessageType.MSG_GAME_AI_END; //AI场结算
        var o = com.snake.socket.CS_GAME_AI_END.fromObject({
            gameId: 100003,
            cont: count,
            res: isWin,
            socre: score
        });
        HallWebSocket.send(cmdId, o);
        // RoomWebSocket.sendData(cmdId, o, false);
    }

    private onAiEnd(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SC_GAME_AI_END = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_GAME_AI_END);
        var msgEndBody = msgBody as com.snake.socket.SC_GAME_AI_END;
        var items: ItemVo[] = [];
        var dic: Dictionary = new Dictionary();
        var item = msgEndBody.items;
        if (item && item.length > 0)
            item.forEach((itemDto) => {
                var itemVo = dic.get(itemDto.itemId);
                if (!itemVo) {
                    itemVo = new ItemVo(itemDto.itemId);
                    itemVo.newAddCnt = itemDto.num;
                    items.push(itemVo);
                    dic.set(itemDto.itemId, itemVo);
                } else {
                    itemVo.newAddCnt = itemVo.newAddCnt + itemDto.num;
                }
            });
        // 根据截图中的写法计算列表居中
        var spaceX = this.propList.spaceX;
        var itemRenderW = (this.propList as any).itemTemplate.width;
        var len: number = items.length;
        var listW: number = len * itemRenderW + spaceX * (len - 1);
        this.propList.repeatX = len;
        this.propList.width = listW;
        this.propList.x = ((this.box_outside.width - this.propList.width) >> 1) - 50;
        this.propList.array = items;
        this.propList.visible = true;
        if (items.length > 2) {
            this.img_qbg.width = 500
        } else {
            this.img_qbg.width = 362
        }
        console.log(items)
        // this.onSetReward(items, []);
        // GlobalDataManager.playerDto.aiScore = this.roomGameOverPush.score;//把分数赋值给玩家
    }

    private saveBestRecord(score: number): void {
        const currentBest = Laya.LocalStorage.getItem("ai_arena_best_record");
        let bestScore = 0;

        if (currentBest) {
            try {
                const record = JSON.parse(currentBest);
                bestScore = record.score || 0;
            } catch (e) {
                console.error("解析当前最好成绩失败:", e);
            }
        }

        if (score > bestScore) {
            const newRecord = {
                score: score,
                stars: NumberUtil.calculateStarCount(score, 100),
                timestamp: Date.now()
            };
            Laya.LocalStorage.setItem("ai_arena_best_record", JSON.stringify(newRecord));
        }
    }

        private playOpenAnimation(): void {
        // 星星闪烁动画
        Laya.timer.once(500, this, () => {
            this.playStarTwinkle();
        });
    }

    private playStarTwinkle(): void {
        this.stars.forEach((star, index) => {
            if (star.alpha === 1) {
                Laya.timer.loop(2000 + index * 200, this, () => {
                    Laya.Tween.to(
                        star,
                        { scaleX: 1.2, scaleY: 1.2 },
                        200,
                        Laya.Ease.sineOut,
                        Laya.Handler.create(this, () => {
                            Laya.Tween.to(star, { scaleX: 1, scaleY: 1 }, 200, Laya.Ease.sineOut);
                        })
                    );
                });
            }
        });
    }
}
