import { ByteEx } from "./ByteEx";

export class DESTool {
    public constructor() {}

    // URL安全的Base64字符集（替换+/为-_，去掉=）
    private static readonly BASE64_CHARS: string = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";

    // 用于解码的查找表
    private static decodeTable: { [key: string]: number } | null = null;

    /**
     * 初始化解码查找表
     */
    private static initDecodeTable(): void {
        if (DESTool.decodeTable) {
            return;
        }
        DESTool.decodeTable = {};
        for (let i = 0; i < DESTool.BASE64_CHARS.length; i++) {
            DESTool.decodeTable[DESTool.BASE64_CHARS.charAt(i)] = i;
        }
    }

    /**
     * URL安全的Base64编码（无填充字符）
     * @param arraybuffer 要编码的数据
     * @returns URL安全的编码字符串
     */
    public static encode(arraybuffer: ArrayBuffer): string {
        const bytes = new Uint8Array(arraybuffer);
        const len = bytes.length;
        let base64 = "";

        for (let i = 0; i < len; i += 3) {
            const byte1 = bytes[i];
            const byte2 = i + 1 < len ? bytes[i + 1] : 0;
            const byte3 = i + 2 < len ? bytes[i + 2] : 0;

            const bitmap = (byte1 << 16) | (byte2 << 8) | byte3;

            base64 += DESTool.BASE64_CHARS.charAt((bitmap >> 18) & 63);
            base64 += DESTool.BASE64_CHARS.charAt((bitmap >> 12) & 63);
            if (i + 1 < len) base64 += DESTool.BASE64_CHARS.charAt((bitmap >> 6) & 63);
            if (i + 2 < len) base64 += DESTool.BASE64_CHARS.charAt(bitmap & 63);
        }

        return base64; // 不添加填充字符
    }

    /**
     * URL安全的Base64解码
     * @param base64String 要解码的Base64字符串
     * @returns 解码后的ArrayBuffer
     */
    public static decode(base64String: string): ArrayBuffer {
        DESTool.initDecodeTable();

        const len = base64String.length;
        // 计算需要的字节数（无填充字符版本）
        const paddingNeeded = (4 - (len % 4)) % 4;
        const totalLen = len + paddingNeeded;
        const bytes = new Uint8Array(Math.floor((totalLen * 3) / 4));
        let byteIndex = 0;

        for (let i = 0; i < len; i += 4) {
            const char1 = DESTool.decodeTable![base64String.charAt(i)] || 0;
            const char2 = i + 1 < len ? DESTool.decodeTable![base64String.charAt(i + 1)] || 0 : 0;
            const char3 = i + 2 < len ? DESTool.decodeTable![base64String.charAt(i + 2)] || 0 : 0;
            const char4 = i + 3 < len ? DESTool.decodeTable![base64String.charAt(i + 3)] || 0 : 0;

            const bitmap = (char1 << 18) | (char2 << 12) | (char3 << 6) | char4;

            bytes[byteIndex++] = (bitmap >> 16) & 255;
            if (i + 2 < len) bytes[byteIndex++] = (bitmap >> 8) & 255;
            if (i + 3 < len) bytes[byteIndex++] = bitmap & 255;
        }

        return bytes.buffer.slice(0, byteIndex);
    }

    /**
     * URL安全编码字符串（UTF-8）
     * @param str 要编码的字符串
     * @returns URL安全的编码字符串（2字符开销）
     */
    public static encodeStr(str: string): string {
        const byte = new ByteEx();
        byte.writeUTFString(str);
        return DESTool.encodeByte(byte);
    }

    /**
     * URL安全解码字符串（UTF-8）
     * @param encodedStr 编码后的字符串
     * @returns 解码后的原始字符串
     */
    public static decodeStr(encodedStr: string): string {
        const decodedByte = DESTool.decodeByte(encodedStr);
        if (!decodedByte) {
            throw new Error("解码失败：无效的编码字符串");
        }
        decodedByte.pos = 0;
        return decodedByte.readUTFString();
    }

    /**
     * URL安全编码字符串（UTF-8 Bytes）
     * @param str 要编码的字符串
     * @returns URL安全的编码字符串（2字符开销）
     */
    public static encodeStr2(str: string): string {
        const byte = new ByteEx();
        byte.writeUTFBytes(str);
        return DESTool.encodeByte(byte);
    }

    /**
     * URL安全解码字符串（UTF-8 Bytes）
     * @param encodedStr 编码后的字符串
     * @returns 解码后的原始字符串
     */
    public static decodeStr2(encodedStr: string): string {
        const decodedByte = DESTool.decodeByte(encodedStr);
        if (!decodedByte) {
            throw new Error("解码失败：无效的编码字符串");
        }
        decodedByte.pos = 0;
        return decodedByte.readUTFBytes();
    }

    /**
     * URL安全编码ByteEx对象（2字符开销）
     * @param byte ByteEx对象
     * @param start 开始位置
     * @param end 结束位置
     * @returns URL安全的编码字符串
     */
    public static encodeByte(byte: ByteEx, start: number = 0, end: number = -1): string {
        if (end < 0) {
            end = byte.length;
        }
        const prefix = DESTool.generatePrefix();
        const suffix = DESTool.generateSuffix();
        const encodedData = DESTool.encode(byte.buffer.slice(start, end));
        return prefix + encodedData + suffix;
    }

    /**
     * URL安全解码ByteEx对象
     * @param encodedStr 编码后的字符串
     * @returns 解码后的ByteEx对象
     */
    public static decodeByte(encodedStr: string): ByteEx | null {
        try {
            if (encodedStr.length < 3) {
                throw new Error("数据长度不足");
            }

            const base64Data = encodedStr.substring(1, encodedStr.length - 1);
            const decodedBuffer = DESTool.decode(base64Data);
            const byte = new ByteEx();
            byte.writeArrayBuffer(decodedBuffer);
            return byte;
        } catch (error) {
            console.error("解码失败:", error);
            return null;
        }
    }

    /**
     * 生成URL安全的随机前缀（1字符）
     * @returns URL安全的随机前缀字符串
     */
    private static generatePrefix(): string {
        const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
        return chars.charAt(Math.floor(Math.random() * chars.length));
    }

    /**
     * 生成URL安全的随机后缀（1字符）
     * @returns URL安全的随机后缀字符串
     */
    private static generateSuffix(): string {
        const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
        return chars.charAt(Math.floor(Math.random() * chars.length));
    }

    /**
     * URL安全加密（异或加密）
     * @param data 要加密的数据
     * @param key 加密密钥
     * @returns URL安全的加密数据
     */
    public static encrypt(data: string, key: string = "defaultKey"): string {
        const byte = new ByteEx();
        byte.writeUTFString(data);

        const buffer = new Uint8Array(byte.buffer);
        const keyBytes = new TextEncoder().encode(key);

        for (let i = 0; i < buffer.length; i++) {
            buffer[i] ^= keyBytes[i % keyBytes.length];
        }

        const encryptedByte = new ByteEx();
        encryptedByte.writeArrayBuffer(buffer.buffer);
        return DESTool.encodeByte(encryptedByte);
    }

    /**
     * URL安全解密（异或解密）
     * @param encryptedData 加密后的数据
     * @param key 解密密钥
     * @returns 解密后的原始数据
     */
    public static decrypt(encryptedData: string, key: string = "defaultKey"): string {
        const decodedByte = DESTool.decodeByte(encryptedData);
        if (!decodedByte) {
            throw new Error("解密失败：无效的加密数据");
        }

        const buffer = new Uint8Array(decodedByte.buffer);
        const keyBytes = new TextEncoder().encode(key);

        for (let i = 0; i < buffer.length; i++) {
            buffer[i] ^= keyBytes[i % keyBytes.length];
        }

        const decryptedByte = new ByteEx();
        decryptedByte.writeArrayBuffer(buffer.buffer);
        decryptedByte.pos = 0;
        return decryptedByte.readUTFString();
    }

    /**
     * 超简化URL安全编码（0字符开销）
     * @param str 要编码的字符串
     * @returns 纯URL安全Base64编码字符串
     */
    public static encodeStrSimple(str: string): string {
        const byte = new ByteEx();
        byte.writeUTFBytes(str);
        return DESTool.encode(byte.buffer);
    }

    /**
     * 超简化URL安全解码（0字符开销）
     * @param encodedStr 编码后的字符串
     * @returns 解码后的原始字符串
     */
    public static decodeStrSimple(encodedStr: string): string {
        const decodedBuffer = DESTool.decode(encodedStr);
        const byte = new ByteEx();
        byte.writeArrayBuffer(decodedBuffer);
        byte.pos = 0;
        return byte.readUTFBytes(decodedBuffer.byteLength);
    }
}
